def get_closest_vowel(word):
    vowels = set('aeiouAEIOU')
    # If word length is less than 3, no vowel can be between two consonants
    if len(word) < 3:
        return ""
    # Iterate from the second last character to the second character (right to left)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            # Check if neighbors are consonants (not vowels)
            if word[i - 1] not in vowels and word[i + 1] not in vowels:
                return word[i]
    return ""
